            decay: method.decay,
            expectedAccepted,
            tokensPerStep,
            draftParamsB,
            draftLayers: method.kind === 'autoregressive-model' ? Math.max(8, Math.round(numLayers * Math.cbrt(draftParamsB / Math.max(modelConfig.totalParamsB, 0.1)))) : (method.draftLayersOfTarget || 0),
